    private int[,] board; // tablero de juego
    private int score; // puntuación actual

    void Start()
    {
        // inicializar el tablero de juego
        board = new int[rows, cols];
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                board[i, j] = Random.Range(0, gems.Length);
            }
        }
    }

    void Update()
    {
        // mover el tablero de juego
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                if (board[i, j] > 0)
                {
                    // cambiar la posición de la gema
                    board[i, j]--;
                    // mover la gema hacia abajo
                    if (i < rows - 1)
                    {
                        board[i + 1, j] = board[i, j];
                        board[i, j] = 0;
                    }
                }
            }
        }
    }

    public void CheckForMatches()
    {
        // verificar si hay matches en la fila
        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                if (board[i, j] > 0)
                {
                    // verificar si hay gemas iguales a la izquierda y derecha
                    if (j > 0 && board[i, j] == board[i, j - 1])
                    {
                        // eliminar las gemas
                        board[i, j - 1] = 0;
                        board[i, j] = 0;
                        // código para generar nuevos gemas
                    }
                }
            }
        }
    }
}
```
